t=t[:start]+'function Invoices({workId,invoices,documents,reload}:{workId:string;invoices:any[];documents:any[];reload:()=>void}){\n const [open,setOpen]=useState(false); const [upload,setUpload]=useState<any>(null);\n const save=async(f:any)=>{await api.post(`/api/works/${workId}/invoices`,f);setOpen(false);reload()};\n const remove=async(r:any)=>{if(!confirm(`¿Eliminar la factura ${r.invoice_number||\'\'}? Solo se permite si todavía no tiene cobros.`))return;try{await fetch(`${(process.env.NEXT_PUBLIC_API_URL||\'https://dirac-admin.onrender.com\').replace(/\\/$/,\'\')}/api/works/${workId}/invoices/${r.id}`,{method:\'DELETE\',headers:process.env.NEXT_PUBLIC_API_KEY?{\'X-API-Key\':process.env.NEXT_PUBLIC_API_KEY}:{}}).then(async x=>{if(!x.ok){const b=await x.json().catch(()=>({}));throw new Error(b.detail||`Error ${x.status}`)}});reload()}catch(e:any){alert(e.message)}};\n const view=async(id:string)=>{const r=await api.get<any>(`/api/work-documents/${id}/signed-url`);if(r.url)window.open(r.url,\'_blank\')};\n const related=(r:any,type:string)=>documents.find((d:any)=>d.document_type===type&&((type===\'factura_cliente\'&&d.related_type===\'work_invoice\'&&d.related_id===r.id)||(type===\'comprobante_pago\'&&d.related_type===\'receivable_payment\'&&d.related_id===r.receivable_id)));\n const doUpload=async(fd:FormData)=>{await api.upload(\'/api/work-documents/upload\',fd);setUpload(null);reload()};\n return <Card><SectionTitle title="Facturación de obra" subtitle="La factura es independiente de los ítems y del avance físico. Ingresá directamente el monto total." action={<button className="primary-button" onClick={()=>setOpen(true)}>+ Nueva factura</button>}/>{invoices.length===0?<Empty text="Todavía no hay facturas emitidas para esta obra."/>:<div className="table-wrap"><table><thead><tr><th>Emisión</th><th>Factura</th><th>Concepto</th><th>Vence</th><th>Total</th><th>Estado</th><th>Documentos</th><th/></tr></thead><tbody>{invoices.map((r:any)=>{const invoiceDoc=related(r,\'factura_cliente\');const paymentDoc=related(r,\'comprobante_pago\');const paid=r.receivable_status===\'cobrado\';const hasCollection=paid||r.receivable_status===\'parcial\';return <tr key={r.id}><td>{dateAR(r.issue_date)}</td><td><b>{r.invoice_number||\'—\'}</b></td><td>{r.description||\'—\'}</td><td>{dateAR(r.due_date)}</td><td><b>{money(r.total_amount)}</b></td><td><Status tone={paid?\'green\':r.receivable_status===\'parcial\'?\'blue\':\'yellow\'}>{r.receivable_status||\'pendiente\'}</Status></td><td><div style={{display:\'flex\',gap:6,flexWrap:\'wrap\'}}>{invoiceDoc?<button className="mini-button" onClick={()=>view(invoiceDoc.id)}>Ver factura</button>:<button className="mini-button" onClick={()=>setUpload({type:\'factura_cliente\',related_type:\'work_invoice\',related_id:r.id,title:`Factura ${r.invoice_number||\'\'}`})}>Subir factura</button>}{hasCollection&&(paymentDoc?<button className="mini-button" onClick={()=>view(paymentDoc.id)}>Ver comprobante</button>:<button className="mini-button" onClick={()=>setUpload({type:\'comprobante_pago\',related_type:\'receivable_payment\',related_id:r.receivable_id,title:`Comprobante de cobro ${r.invoice_number||\'\'}`})}>Subir comprobante</button>)}</div></td><td><button className="mini-button danger-text" onClick={()=>remove(r)}>Eliminar</button></td></tr>})}</tbody></table></div>}{open&&<SimpleWorkInvoiceModal onClose={()=>setOpen(false)} onSave={save}/>} {upload&&<RelatedUploadModal workId={workId} documentType={upload.type} relatedType={upload.related_type} relatedId={upload.related_id} defaultTitle={upload.title} onClose={()=>setUpload(null)} onSave={doUpload}/>}</Card>\n}\n\nfunction SimpleWorkInvoiceModal({onClose,onSave}:{onClose:()=>void;onSave:(x:any)=>Promise<void>}){\n const [f,setF]=useState<any>({document_number:\'\',description:\'\',issue_date:new Date().toISOString().slice(0,10),due_date:\'\',amount:\'\',notes:\'\',vat_rate:21});\n const [saving,setSaving]=useState(false);\n const total=Number(f.amount||0);\n const vatRate=Number(f.vat_rate||0);\n const divisor=1+(vatRate/100);\n const net=divisor>0?total/divisor:total;\n const vat=total-net;\n const submit=async(e:any)=>{e.preventDefault();if(total<=0){alert(\'Ingresá un monto mayor a cero\');return}setSaving(true);try{await onSave({...f,amount:total,vat_rate:vatRate,due_date:f.due_date||null})}catch(x:any){alert(x.message)}finally{setSaving(false)}};\n return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><h2>Nueva factura de obra</h2><p>La factura no se vincula a ítems. Ingresá directamente el monto total, IVA incluido.</p></div><button className="close-button" onClick={onClose}>×</button></div><form onSubmit={submit}><div className="form-grid"><label className="field"><span>Número de factura</span><input value={f.document_number} onChange={e=>setF({...f,document_number:e.target.value})}/></label><label className="field"><span>Concepto</span><input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label className="field"><span>Fecha emisión</span><input type="date" value={f.issue_date} onChange={e=>setF({...f,issue_date:e.target.value})}/></label><label className="field"><span>Vencimiento</span><input type="date" value={f.due_date} onChange={e=>setF({...f,due_date:e.target.value})}/></label><label className="field"><span>Monto total (IVA incluido) *</span><input type="number" min="0.01" step="0.01" value={f.amount} onChange={e=>setF({...f,amount:e.target.value})}/></label><label className="field"><span>IVA</span><select value={f.vat_rate} onChange={e=>setF({...f,vat_rate:Number(e.target.value)})}><option value={0}>0%</option><option value={10.5}>10,5%</option><option value={21}>21%</option><option value={27}>27%</option></select></label><label className="field full"><span>Notas</span><textarea rows={3} value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></label></div><div className="modal-note" style={{display:\'grid\',gap:6}}><div>Neto incluido: <b>{money(net)}</b></div><div>IVA incluido {vatRate}%: <b>{money(vat)}</b></div><div style={{fontSize:18}}>TOTAL FACTURA: <b>{money(total)}</b></div></div><div className="modal-actions"><button type="button" className="ghost-button" onClick={onClose}>Cancelar</button><button className="primary-button" disabled={saving||total<=0}>{saving?\'Guardando…\':\'Crear factura\'}</button></div></form></div></div>\n}\n\n'+t[end:]
